const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routes={home:'Home',journey:'The fan journey',framework:'The Next Fan Framework',strategy:'Strategy builder',lab:'Content Lab',film:'The Film Room',research:'Research & insights',xi:"John’s Starting XI",about:"Why I’m asking this",thesis:'The thesis',sources:'Sources'};
const btn=(text,route,cls='')=>`<a class="btn ${cls}" href="#${route}">${text}<span>↗</span></a>`;
const tag=(text='Thesis evidence pending')=>`<span class="evidence">${text}</span>`;
const quote=text=>`<aside class="quote"><small>JG’S TAKE · EDITORIAL COPY</small><p>${text}</p></aside>`;
const heading=(k,t,p='')=>`<div class="page-head"><div class="eyebrow">${k}</div><h1>${t}</h1>${p?`<p>${p}</p>`:''}</div>`;
const waiting=(name='Research data')=>`<div class="waiting"><div class="symbol">＋</div><div class="eyebrow" style="justify-content:center">${name}</div><h3>Waiting for John’s research data.</h3><p class="muted">No estimates. No invented findings. This space is reserved for the evidence.</p></div>`;
const researchSplit=(text='This proposed relationship will be investigated through the thesis.',take='Going viral is great. Creating a fan is better.')=>`<div class="grid2 mt"><div class="card"><div class="eyebrow">What the research says</div>${tag()}<p>${text} No thesis findings have been supplied.</p></div><div class="card"><div class="eyebrow">What sports organizations can do</div><p>Use the journey to ask what happens after attention: do people return, contribute, feel connected or advocate over time? Evaluate these outcomes separately rather than treating reach as loyalty.</p><small>Editorial recommendation, not a research finding.</small>${quote(take)}</div></div>`;
function img(id,label='',height=''){const x=NF.images.find(i=>i.id===id);if(!x)return '';return `<figure class="photo"><img src="${esc(x.url)}" alt="${esc(x.alt)}" loading="lazy" ${height?`style="height:${height}"`:''}>${label?`<span class="photo-label">${label}</span>`:''}<figcaption>${esc(x.caption)} · <a href="${esc(x.source)}" target="_blank" rel="noopener">${esc(x.author)}</a> · <a href="${esc(x.licenseUrl)}" target="_blank" rel="noopener">${esc(x.license)}</a> · display crop</figcaption></figure>`}
const stageKickers=['First contact','Come back','Join in','Belong','Stick around'];
function stages(selected=-1,expanded=false){return `<div class="journey-strip ${expanded?'home-stage-strip':''}">${NF.stages.map((s,i)=>`<button class="stage-button ${selected===i?'selected':''}" data-stage="${i}" aria-pressed="${selected===i}"><span class="n">0${i+1}</span><span class="arrow">↗</span>${expanded?`<span class="stage-kicker">${stageKickers[i]}</span>`:''}<h3>${s.name}</h3><p>${expanded?s.description:s.verb}</p></button>`).join('')}</div>`}
function stageDetail(i){const s=NF.stages[i];return `<div class="stage-detail"><div class="grid2"><div><div class="eyebrow">0${i+1} / The proposed journey</div><h3>${s.verb}</h3><p>${s.description}</p><ul>${s.behaviors.map(b=>`<li>${b}</li>`).join('')}</ul></div><div>${tag('Conceptual framework · not yet validated')}<h4 class="mt">What to look for</h4><p>${s.metric}</p><h4>What it doesn’t prove</h4><p>${s.risk}</p>${quote(s.take)}</div></div></div>`}
function home(){const hero=NF.images.find(i=>i.id==='hazard');return `<section class="hero"><div class="hero-copy"><div class="eyebrow">A different way into the game</div><h1>I became a<br>Chelsea fan<br>because of<br><em>Eden Hazard.</em></h1><p>Today, the next Eden Hazard might find you before you ever find him.</p>${btn('Follow the fan journey','journey','blue')}<small class="muted mt">A personal story. A digital sports media research lab.</small></div><div class="hero-media">${hero?`<img src="${hero.url}" alt="Eden Hazard playing for Chelsea in 2012"><a class="photo-credit" href="${hero.source}" target="_blank" rel="noopener">wonker · CC BY 2.0 · display crop ↗</a>`:''}<span class="hero-tag">BEFORE THE FYP, THERE WAS HAZARD.</span><div class="hero-overlay"><div class="big-num">01 → ∞</div><h3>One player.<br>A whole new world.</h3><p>My way in was Chelsea. What’s yours?</p></div></div></section><div class="ticker"><span>Discovery. Engagement. Participation. Loyalty.</span><span>A research & sports marketing lab by John Gates</span></div>
<section class="section"><div class="section-top"><div class="eyebrow">01 / How it started</div><span class="meta">PERSONAL EXPERIENCE ≠ ACADEMIC EVIDENCE</span></div><div class="split"><h2>That was my fan journey.<br>How might digital sports media start someone else’s?</h2><div><p>Hazard got my attention. Chelsea became my team. In between were the matches, the players, the culture and the feeling that this club somehow belonged to me.</p><div class="chips">${['Eden Hazard','Player interest','Watched Chelsea','Learned the team','Followed the culture','Identified with the club','Chelsea fan'].map(t=>`<span class="pill">${t}</span>`).join('')}</div><p class="note">An autobiographical illustration, not a finding.</p></div></div></section>
<section class="section blue-bg"><div class="eyebrow">The question behind everything</div><h2 class="question">${NF.question}</h2><p>Or, in normal-person language:</p><h3>How does somebody go from “Who the hell is that?” to “That’s my team”?</h3><p>For sports organizations: once you earn someone’s attention, how can you develop a sustained fan relationship? This project investigates that question without assuming a view becomes loyalty.</p></section>
<section class="section"><div class="section-top"><div><div class="eyebrow">02 / More than a seat</div><h2>FANDOM HAS<br>MORE ADDRESSES NOW.</h2></div><p>The stadium. The couch. The group chat. The feed. What does being a sports fan actually look like in 2026?</p></div><div class="montage">${img('basketball','In the stands')}${img('women','In the moment')}${img('bar','Together, elsewhere')}</div><div class="chips mt">${['Watch parties','Fan edits','Fantasy leagues','Highlights','Second screens','Athlete merchandise','Group chats'].map(x=>`<span class="pill">${x}</span>`).join('')}</div><p class="note">Photography illustrates sports settings, not evidence of audience trends or media habits.</p></section>
<section class="section dark"><div class="section-top"><div><div class="eyebrow">03 / The proposed framework</div><h2>A VIEW IS JUST<br>THE OPENING WHISTLE.</h2></div><p>Five connected stages. Plenty of detours. Click a stage to explore what might happen next.</p></div>${stages(-1,true)}<p class="note">A working conceptual model. Fans can skip stages, move backward or leave entirely.</p>${quote('Sports fans say “we won” after contributing absolutely nothing to the victory. That level of identification is exactly why fandom is fascinating.')}</section>
<section class="section"><div class="section-top"><div><div class="eyebrow">04 / A different perspective</div><h2>EMPTY SEATS.<br>FULL FEEDS.</h2></div><p>The stands tell one story. The feed tells another. A photograph cannot tell us how many people care.</p></div><div class="grid2">${img('empty','The visible seat')}${img('stadium','The shared place')}</div><div class="split mt"><h3>Is the fan in Row 4 inherently “more of a fan” than someone 1,000 miles away?</h3><div><p>What if that person watches highlights, debates the game online, buys the jersey and creates content? The research gets to investigate. The photo doesn’t get to decide.</p>${btn('Explore modern fandom','journey')}</div></div><div class="modern-fandom-grid mt-lg"><article class="modern-fandom-card stadium-card"><span>01 / The stadium</span><div><h3>FANDOM STILL<br>LIVES HERE.</h3><p>Tickets, chants, rituals and shared physical experiences remain powerful expressions of sports identity.</p></div></article><article class="modern-fandom-card feed-card"><span>02 / The feed</span><div><h3>THE NEW<br>FRONT DOOR.</h3><p>A highlight, athlete clip or recommendation can introduce someone to a player or team before they ever watch a full game.</p></div></article><article class="modern-fandom-card community-card"><span>03 / The group chat</span><div><h3>FANS DON’T<br>JUST WATCH.</h3><p>Memes, fantasy, reactions, debates and fan-created content turn watching sports into something fans actively contribute to.</p></div></article></div><div class="fandom-addresses-statement"><span>THE STADIUM DIDN’T DISAPPEAR.</span><strong>FANDOM JUST GOT MORE ADDRESSES.</strong></div>${quote('I found Chelsea through Eden Hazard. The next fan might find their Hazard while scrolling at 1:14 a.m. The entry point changed. The attachment can still become real.')}<p class="note">Nationals Park was photographed during a tour while the team was away. Empty seating is not evidence of an attendance problem. “Full feeds” and the three address cards are editorial framing, not measured findings.</p></section>
<section class="section blue-bg"><div class="split"><div><div class="eyebrow">From the question to the game plan</div><h2>DON’T JUST<br>CHASE THE SCROLL.</h2></div><div><p>Choose your organization, audience and goal. Build a practical starting point for your content strategy, with the evidence gaps left visible.</p>${btn('Build your game plan','strategy','yellow')}<p class="meta">Working tools. Provisional strategy. No invented findings.</p></div></div></section>
<section class="section"><div class="section-top"><div><div class="eyebrow">Inside the lab</div><h2>RESEARCH WITH<br>SOMETHING TO DO.</h2></div>${btn('Explore the research','research')}</div><div class="grid3"><a href="#lab" class="card feature-card"><span class="eyebrow">Test the approach</span><h3>THE CONTENT LAB</h3><p>Fourteen content formats. Different ways into fandom.</p><span>Find an angle ↗</span></a><a href="#xi" class="card feature-card"><span class="eyebrow">The final team sheet</span><h3>JOHN’S<br>STARTING XI</h3><p>Eleven positions reserved for eleven research-supported principles.</p><span>Step onto the pitch ↗</span></a><a href="#about" class="card feature-card"><span class="eyebrow">The person asking</span><h3>PLAYER. COACH.<br>FAN. MARKETER.</h3><p>Four perspectives. One question about who comes next.</p><span>Meet John ↗</span></a></div></section>`}
function journey(){return heading('The fan journey','BEFORE THE FYP,<br>THERE WAS HAZARD.','My path into Chelsea fandom began with a player. This is my story, not a study result.')+`<section class="section dark"><div class="split"><div>${img('hazard','The player who started it')}</div><div><div class="eyebrow">John’s mini case study</div><h2>ONE PLAYER.<br>THEN MY TEAM.</h2><div class="lab-list mt" id="story-list">${['Eden Hazard','Player interest','Watched Chelsea','Learned the team','Followed the culture','Identified with the club','Chelsea fan'].map((x,i)=>`<button style="color:inherit" data-story="${i}">0${i+1} · ${x} ↗</button>`).join('')}</div><p id="story-copy">Select a moment in my journey.</p></div></div><p class="mt">My path started with a player. Digital sports media opens a bigger question: how might a highlight, a creator, a live stream or an online community become the start of a lasting sports relationship? TikTok’s recommendations are one pathway to investigate alongside others.</p>${btn('Enter the research','research','yellow')}</section>
<section class="section"><div class="eyebrow">Then + now, not then versus now</div><h2>HOW FANDOM FOUND YOU.</h2><p>Tap the pathways that sound familiar. More than one can be true.</p><div class="then-now mt"><div><h3>THEN</h3>${['Family','Geography','Television','Local team','Favorite player','Newspaper','SportsCenter','Friends','Going to games'].map(x=>`<button data-path="${x}" aria-pressed="false">${x}</button>`).join('')}</div><div><h3>NOW</h3>${['For You Page','Athlete clips','Creators','Highlights','Memes','Algorithms','Fantasy sports','Group chats','Fan edits','Behind-the-scenes access','Viral moments'].map(x=>`<button data-path="${x}" aria-pressed="false">${x}</button>`).join('')}</div></div><p id="path-result" class="status" aria-live="polite">Your pathways will appear here. This reflection is not collected as research.</p><h3>What happens when geography is no longer the gatekeeper of fandom?</h3><p>Traditional pathways remain. The thesis investigates how digital sports media fits alongside them, from first discovery to participation and long-term loyalty.</p></section>
<section class="section dark"><div class="eyebrow">The places fandom happens</div><h2>THE SAME SPORT.<br>DIFFERENT WAYS IN.</h2><div class="grid3 mt">${img('nfl','NFL')}${img('nhl','NHL')}${img('mls','MLS')}${img('wnba','Women’s professional sports')}${img('basketball','College basketball')}${img('stadium','European soccer')}${img('sparse','Baseball')}${img('bar','The sports bar')}</div><p class="note">Images show particular places and moments. They do not establish attendance trends or levels of fan loyalty.</p></section>
<section class="section"><div class="section-top"><div><div class="eyebrow">A little self-scouting</div><h2>ARE YOU ACTUALLY A FAN?</h2></div><p>Eleven questions. Zero authority to revoke your fan card.</p></div>${quiz()}</section><section class="section blue-bg"><div class="eyebrow">Player &gt; team?</div><h2>DO YOU LOVE THE TEAM<br>OR DO YOU JUST LOVE THAT DUDE?</h2><p>If your favorite player gets traded tomorrow, where does your loyalty go?</p><div class="poll-options">${['I stay with the team','I follow the player','Both, somehow','Honestly, it depends'].map(x=>`<button data-poll="${x}" aria-pressed="false">${x} ↗</button>`).join('')}</div><p id="poll-result" aria-live="polite">A personal reflection, not a live survey. No responses are collected or aggregated.</p><p>Athlete branding, parasocial relationships and player movement raise questions about where attachment lives. We are not assuming the answer.</p></section><section class="section"><div class="eyebrow">Participatory culture</div><h2>FANS AREN’T JUST THE<br><s>AUDIENCE.</s> PARTICIPANTS.</h2><p>Fan edits. Reaction videos. Memes. Duets. Stitches. Predictions. Fantasy sports. Debates. Creator analysis. Inside jokes. Traditions.</p><p>These are ways fans can contribute to the story surrounding sports. Whether those contributions lead to identity or loyalty is a question for the research.</p>${researchSplit('The thesis will examine participation and its relationship to fan identity.','At some point you stop consuming the joke and become part of the joke.')}</section>`}
function framework(){return heading('Developed by John Gates','THE NEXT FAN FRAMEWORK.','A proposed model of how discovery might become something deeper. A map to investigate, not a promise of conversion.')+`<section class="section"><div class="framework-wrap"><div class="personalization">DIGITAL SPORTS MEDIA · THE SURROUNDING ENVIRONMENT</div>${stages(0)}<div class="backpaths"><span>↔ Return to earlier stages</span><span>↗ Skip a stage</span><span>↘ Follow an athlete, not a team</span><span>↘ Leave the journey</span></div><div id="stage-panel">${stageDetail(0)}</div></div><p class="note">Social platforms, digital viewing, athlete content and fan communities provide contexts for this journey. Personalization is one possible mechanism, not a required first step. Click stages to inspect the proposed behaviors and their limits. The sequence is conceptual and has not been validated by John’s thesis.</p>${researchSplit()}</section>
<section class="section dark"><div class="eyebrow">The scoreboard isn’t the whole game</div><h2>CONGRATS ON THE VIEWS.<br>NOW WHAT?</h2><div class="grid2 mt"><div><span class="evidence">Illustrative numbers only · not actual results</span>${[['1,400,000','views'],['87,000','likes'],['6,400','shares']].map(([n,t])=>`<div class="metric-row"><span class="metric-num">${n}</span><span>${t}</span></div>`).join('')}</div><div><ul class="checklist">${['Did they follow?','Did they come back?','Did they watch a game?','Did they participate?','Did they care about the athlete or the team?','Did they buy anything or attend?','Are they still here six months later?'].map(x=>`<li>${x}</li>`).join('')}</ul></div></div><h2 class="mt-lg">ATTENTION ≠ LOYALTY</h2><p>Attention can be the beginning of loyalty. It is not a substitute for observing whether a relationship lasts.</p></section>
<section class="section"><div class="eyebrow">An extremely expensive metaphor</div><h2>THE $17 HOT DOG TEST.</h2><p>How far did digital fandom actually travel? Tap a step.</p><div class="hotdog-track">${['Saw a video','Watched another','Followed','Commented','Joined the community','Watched a game','Bought a jersey','Bought a ticket','Paid an offensive amount for stadium food','Still came back'].map((x,i)=>`<button data-hotdog="${i}" class="${i===0?'active':''}"><span>${String(i+1).padStart(2,'0')}</span>${x}</button>`).join('')}</div><div id="hotdog-detail" class="status" aria-live="polite">Attention: a first exposure. It tells us a video was encountered, not that a fan was created.</div><p class="note">Illustrative teaching pathway, not a validated scale. $17 is a joke, not a quoted price. People can skip steps, return or leave. Commercial actions depend on access, money and geography; spending is not required to be a fan.</p>${quote('Getting 2 million views is cool. Getting somebody to willingly pay $17 for a stadium hot dog might tell us a little more.')}</section>`}
const orgs=['Professional Team','College Athletics','League','Athlete','Sports Brand','Sports Media Company'],audiences=['Existing fans','Casual fans','Young fans','Fans outside your geographic market','Fans of an individual athlete','People unfamiliar with your sport'],goals=['Discovery','Engagement','Participation','Community','Identity','Loyalty','Game viewership','Attendance','Merchandise consideration'],assets=['Highlights','Athletes','Behind-the-scenes access','Archives','Fan content','Educational content','Creators','Humor'];
const select=(id,label,options)=>`<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}">${options.map(x=>`<option>${x}</option>`).join('')}</select></div>`;
function strategy(){return heading('The sports marketing strategy builder','YOUR NEXT FAN.<br>YOUR GAME PLAN.','Tell us who you’re reaching and what you have. Get a concrete planning draft, with the research gaps clearly marked.')+`<section class="section"><form id="strategy-form"><div class="controls">${select('org','Who are you?',orgs)}${select('audience','Who are you trying to reach?',audiences)}${select('goal','What do you want?',goals)}<fieldset class="field"><legend>What content do you have? Choose at least one.</legend><div class="checks">${assets.map((x,i)=>`<label class="check"><input type="checkbox" name="assets" value="${x}" ${i===0?'checked':''}>${x}</label>`).join('')}</div></fieldset></div><div class="btn-row mt"><button class="btn blue" type="submit">Build my game plan <span>↗</span></button><button class="btn" type="reset">Reset</button></div><p class="note">Recommendations are editorial planning hypotheses. They are not research findings or predictions of fan conversion.</p><p id="form-error" role="alert"></p></form><div id="game-plan" aria-live="polite"></div></section>`}
function createPlan(org,audience,goal,chosen){const stage=['Community'].includes(goal)?'Participation':['Game viewership','Attendance','Merchandise consideration'].includes(goal)?'Loyalty':goal;const s=NF.stages.find(s=>s.name===stage);const approach={Discovery:'Start with an accessible moment, explain why it matters and offer a clear next step.',Engagement:'Build a repeatable series around one recognizable story. Invite a specific response.',Participation:'Give fans a clear contribution to make, then respond and credit their work.',Identity:'Connect personal stories with team traditions. Leave room for people who are new.',Loyalty:'Create reasons to return over time. Connect the content to a voluntary next action without treating a purchase as proof of belonging.'}[stage];const audienceTip={ 'Existing fans':'Build on shared context without assuming everyone follows every roster change.','Casual fans':'Explain the stakes without homework.','Young fans':'Use accessible explanations and age-appropriate prompts; avoid soliciting personal information.','Fans outside your geographic market':'Offer context, time-zone-friendly scheduling and ways to participate remotely.','Fans of an individual athlete':'Create a bridge from that athlete to teammates and team stories. Do not assume attachment transfers.','People unfamiliar with your sport':'Explain one rule or story at a time and welcome basic questions.'}[audience];const formats=chosen.map(a=>({'Highlights':'A moment + a short context explainer','Athletes':'A recurring athlete Q&A','Behind-the-scenes access':'A permission-cleared day-in-the-life series','Archives':'Then-and-now storytelling with verified context','Fan content':'A credited fan response series','Educational content':'One question, one clear answer','Creators':'A collaboration built around an audience-relevant story','Humor':'An editable reaction prompt grounded in a real sports moment'}[a]));const commercial={Attendance:'Track attributable ticket interest and purchases using consent-aware campaign links. Compare access and schedule barriers.', 'Game viewership':'Track clicks to authorized viewing information and repeat viewing when reliably measurable.', 'Merchandise consideration':'Track product interest separately from purchases, and avoid equating either with identity.'}[goal]||s.metric;return {org,audience,goal,chosen,stage,items:[['Recommended fan journey stage',`${stage}. This is an editorial match to your goal, not a measured prediction.`],['Recommended content approach',`${approach} ${audienceTip}`],['Content formats',formats.join(' • ')],['Why it fits',`For a ${org.toLowerCase()} reaching ${audience.toLowerCase()}, the draft connects your available content to ${goal.toLowerCase()}. Test whether the audience takes the intended next step.`],['Digital media considerations','Choose a channel that fits the audience and intended action: short-form platforms such as TikTok or Instagram, YouTube, digital viewing, fan communities or team-owned channels. Adapt context and accessibility to the format. Check media rights and platform requirements. Exposure and lasting attachment are not guaranteed.'],['What sports organizations can do','Offer a clear next step after initial attention, then examine whether people return, contribute or identify with the organization over time. Track viewership, attendance, merchandise interest and advocacy separately. These are planning suggestions, not evidence that content causes those outcomes.'],['Community strategy',`${audienceTip} Ask one answerable question, respond consistently and set moderation boundaries. Credit contributions and obtain permission before reuse.`],['Metrics',commercial],['What NOT to obsess over','A single viral post, raw likes or follower counts without return behavior and audience fit.'],['Potential risks',`${s.risk} Protect athlete and fan consent, verify media rights and avoid conclusions from a short campaign.`],['Research supporting this recommendation','This plan is an editorial application of the conceptual journey. No academic finding or causal effect is claimed.']]}}
let latestPlan=null;
function planHtml(p){return `<div class="plan"><div class="plan-head"><div><div class="eyebrow">${esc(p.org)} / ${esc(p.goal)}</div><h2>YOUR GAME PLAN.</h2></div><button class="btn yellow" id="export-plan">Download game plan ↓</button></div><div class="status">PROVISIONAL EDITORIAL DRAFT · Audience: ${esc(p.audience)} · Thesis evidence pending</div><div class="plan-grid">${p.items.map(([k,v])=>`<div class="plan-cell"><h4>${k}</h4><p>${esc(v)}</p></div>`).join('')}</div></div>`}
function lab(){return heading('The Content Lab','SAME SPORT.<br>FOURTEEN DIFFERENT ANGLES.','Explore how a content format could support a fan relationship. These are planning hypotheses and invented concept examples, not case-study findings.')+`<section class="section"><div class="lab"><div class="lab-list" aria-label="Content formats">${NF.formats.map((f,i)=>`<button data-format="${i}" class="${i===0?'active':''}" aria-pressed="${i===0}">${f[0]} ↗</button>`).join('')}</div><div id="format-panel">${formatDetail(0)}</div></div></section>`}
function formatDetail(i){const f=NF.formats[i];return `<div class="eyebrow">Format ${String(i+1).padStart(2,'0')} / 14</div><h2>${f[0].toUpperCase()}</h2><div class="mt">${tag('Editorial hypothesis · research support pending')}</div><div class="plan-grid mt">${[['Proposed best fan stage',f[1]],['Potential audience',f[2]],['Why it could work',f[3]],['Potential downside',f[4]],['Useful metrics',f[5]],['Example concept · not a real case study',f[6]],['Research support','Waiting for John’s research data. This relationship has not been established by the thesis.']].map(([k,v])=>`<div class="plan-cell"><h4>${k}</h4><p>${v}</p></div>`).join('')}</div>`}
const questions=['Do you watch full games?','Do you watch highlights?','Do you follow individual players?','Do you follow the team?','Have you bought merchandise?','Have you attended a game?','Do you participate in fan communities?','Do you create or share sports content?','Do you play fantasy sports?','Would you watch this team if its star player left?','Do you know enough obscure roster information that you should probably go outside?'];
function quiz(){return `<div class="status">Exploratory engagement feature. Not a validated academic measurement instrument. Answers stay in this page and are not collected.</div><form id="quiz-form">${questions.map((q,i)=>`<div class="quiz-row"><label for="q${i}">${String(i+1).padStart(2,'0')} / ${q}</label><select id="q${i}" required><option value="">Choose</option><option value="1">Yes</option><option value="0">No</option></select></div>`).join('')}<button class="btn blue mt" type="submit">Give me my scouting report ↗</button><button class="btn mt" type="reset">Start again</button></form><div id="quiz-result" aria-live="polite"></div>`}
function film(){return heading('The Film Room','LET’S WATCH THE TAPE.','The first THE NEXT FAN case study: a player-led doorway into club fandom.')+`<section class="section" id="hazard-case"><div class="eyebrow">Personal illustration · JG’s take</div><h2>TAPE 001: EDEN HAZARD</h2><p class="lead">When the player is the doorway to the club.</p><div class="film"><div class="tape-media"><div class="film-screen"><video controls playsinline preload="metadata" width="576" height="768" aria-label="Tape 001: Eden Hazard" aria-describedby="tape-description"><source src="media/eden-hazard.mp4" type="video/mp4">Your browser does not support this video. <a href="media/eden-hazard.mp4">Open the Eden Hazard video</a>.</video></div><p class="note" id="tape-description">A Hazard edit combining discussion, match footage and memorable moments. Use the player controls for playback and sound.</p><div class="card mt"><div class="eyebrow">John’s personal connection</div><h3>HAZARD LEFT. I STAYED.</h3><p>Hazard was my entry point into Chelsea. What began as interest in one player became interest in the club. Hazard eventually left. I stayed.</p><p>Apparently, my Chelsea membership did not come with a player-transfer clause.</p><p>That’s the question behind THE NEXT FAN: how does initial sports discovery develop into long-term fandom?</p><small>My experience is a personal illustration, not proof that every fan follows this pathway.</small></div></div><div class="film-panel"><div class="eyebrow">John’s breakdown</div><p class="note">Personal interpretation and sports-marketing recommendations. No audience outcomes are claimed.</p><h4>Discovery</h4><p>Hazard is the hook. A viewer does not necessarily need an existing relationship with Chelsea or even the Premier League to be interested. His skill, personality, reputation and visually compelling moments can provide an entry point into the larger Chelsea ecosystem.</p><h4>Engagement</h4><p>The content gives the viewer more than one isolated highlight. Discussion, match footage and memorable Hazard moments offer multiple reasons to keep watching, search for more content or learn about the player and club. These are possibilities, not measured responses.</p><h4>Participation</h4><p>A recognizable player gives people something to talk about: Hazard’s ability, comparisons with other players and his best moments. Those conversations could connect viewers with Chelsea and Premier League fan communities. We have no verified evidence that this specific video caused participation.</p><h4>Identity</h4><p>Eden Hazard was my original entry point into Chelsea fandom. Interest in the individual player eventually expanded into identification with Chelsea itself. That is my experience, not a universal fan pathway.</p><h4>Loyalty potential</h4><p>Hazard eventually left Chelsea. I remained a Chelsea supporter. The athlete can be the entry point, while the organization can become the lasting identity. My story illustrates THE NEXT FAN concept; it does not establish a causal relationship.</p><h4>What worked</h4><p>In my reading, star power and recognizable personalities create an immediate hook. Storytelling gives the spectacular athletic moments context, while short-form editing keeps moving between discussion and action. Nostalgia adds emotional connection for someone like me. The skill is also accessible: you do not need extensive football knowledge to find a moment compelling. These are creative strengths I see, not verified performance findings.</p><h4>What I’d change</h4><p>My sports-marketing recommendation: give that player-driven attention somewhere to go.</p><p><strong>HAZARD → CHELSEA → CLUB HISTORY → CURRENT PLAYERS → MATCHES → COMMUNITY</strong></p><p>I’d pair the edit with a Chelsea history follow-up, a current-player introduction and clear links to match information and fan community spaces. The opportunity is not simply generating views around one athlete. It is creating pathways toward a deeper relationship with the organization. This is a proposed content sequence, not a guaranteed or linear fan journey.</p><h4>Research connection</h4><p>A star athlete can serve as the digital doorway into a sports organization. The larger question is whether that initial player-driven discovery can develop into engagement, participation, identity and eventually loyalty to the organization itself.</p><small>Conceptual interpretation to investigate, not causal proof from this video.</small><div class="card mt"><div class="eyebrow">What the research says</div><p>This case study supplies no research findings or verified audience analytics. John’s story and recommendations remain separate from academic evidence. The thesis must investigate whether, how and for whom these connections occur.</p></div></div></div><div class="mt-lg"><div class="eyebrow">The future case-study shelf</div><h2>EVERY SPORT HAS A STORY.</h2><p>Choose a sport to inspect the case-study structure. These are empty research slots, not completed examples.</p><div class="chips">${NF.leagues.map(x=>`<button class="pill" data-case="${x}">${x} ↗</button>`).join('')}</div></div></section>`}
function research(){return heading('Research & insights','THE EVIDENCE<br>GETS THE FINAL WORD.','The dashboard will grow with the thesis. For now, the architecture is ready and the findings remain unfilled.')+`<section class="section"><div class="status">RESEARCH STATUS · Literature review, methodology and thesis findings have not been supplied to this site. All framework relationships remain provisional.</div><div class="grid3">${['Behavior distributions','Audience pathways','Digital to offline actions'].map(t=>waiting(t)).join('')}</div><div class="section-top mt-lg"><div><div class="eyebrow">Purpose before decoration</div><h2>THE VISUAL RESEARCH DESK.</h2></div><p>Every finished graphic will connect to a specific source or thesis finding. No decorative percentages.</p></div><div class="grid3">${['The modern fan journey','How personalization works','Passive → active fandom','Athlete → team connection','Digital action → offline action','Content type × fan stage','What a view actually tells you','The second-screen fan','Traditional + algorithmic discovery'].map((t,i)=>`<button class="card feature-card" data-infographic="${i}" style="text-align:left;color:inherit"><span class="eyebrow">Visual study / ${String(i+1).padStart(2,'0')}</span><h3>${t}</h3><span class="evidence">Evidence pending · open brief ↗</span></button>`).join('')}</div>${researchSplit()}<div class="btn-row mt">${btn('Open the research library','sources','blue')}${btn('Read the actual thesis','thesis')}</div></section>`}
function xi(){return heading('John’s Starting XI','11 RULES FOR WINNING<br>THE NEXT SPORTS FAN.','The team sheet is ready. The principles earn their place through the research.')+`<section class="section"><div class="grid2"><div class="pitch"><div class="formation">${Array.from({length:11},(_,i)=>`<button class="player" data-player="${i+1}"><span class="shirt">${String(i+1).padStart(2,'0')}</span><span>Research Finding</span></button>`).join('')}</div></div><div><div class="eyebrow">4–3–3 / Developed by John Gates</div><h2>NO ONE MAKES<br>THE XI ON HYPE.</h2><p>Each position will become one practical recommendation backed by the completed thesis. Click a player to see the structure.</p>${tag('All eleven principles awaiting research')}<ul class="checklist">${['The principle','What the research found','Why it matters','What a sports marketer should do','Metrics','Example','JG’s take'].map(x=>`<li>${x}</li>`).join('')}</ul><p class="note">The formation is a visual navigation device. It does not rank the strength of evidence or imply tactical relationships.</p></div></div></section>`}
function about(){return heading('Player / Coach / Fan / Marketer','WHY I’M ASKING<br>THIS QUESTION.','I’ve spent much of my life around sports. Now I want to understand how the next generation may arrive there differently.')+`<section class="section"><div class="split"><div><h2>JOHN GATES.</h2><p>I played Division I college soccer at Loyola Chicago and Lindenwood, and I’ve continued playing competitive soccer beyond college. I also coach soccer, which means I spend plenty of time around young athletes whose sports world looks different from the one I grew up in.</p><p>I’m pursuing a master’s degree in digital and social media marketing at Lindenwood University. Professionally, I’m interested in sports marketing, social media strategy and fan engagement.</p><p>And I’m a fan. Hazard made me care about Chelsea. I want to understand what makes someone else care, especially when their first encounter might be a highlight, a creator or a community they never expected to join.</p></div><div class="portrait"><div id="portrait-preview"><strong>JG</strong><p>John’s professional photo</p><small>Portrait to be supplied. Preview a replacement below.</small></div><label for="portrait-upload" class="btn mt">Choose photo preview</label><input id="portrait-upload" type="file" accept="image/*" hidden><p class="note">Private, session-only preview. Send John’s final photo in chat to add it to the site permanently.</p></div></div><div class="grid2 mt-lg">${[['PLAYER','I understand the sport from inside the game. The details on the field and the story around it both matter.'],['COACH','I work with younger athletes who are growing up with a different set of pathways into sport.'],['FAN','I know what it feels like when a team becomes “we,” even when I have no business taking credit.'],['MARKETER','I want to know what turns attention into a relationship, and how organizations can support that responsibly.']].map(([t,p])=>`<div class="card"><div class="eyebrow">One of four lenses</div><h3>${t}</h3><p>${p}</p></div>`).join('')}</div><div class="mt-lg"><div class="eyebrow">The question behind the question</div><h2>HOW DOES THE NEXT FAN<br>BECOME A FAN?</h2><p>These four perspectives explain why I’m asking. The research will determine what I can claim.</p></div></section>`}
function thesis(){return heading('The academic page','YES, THERE’S<br>AN ACTUAL THESIS.','For anyone who looked at the $17 hot dog graphic and thought, “But where’s the methodology?” Welcome.')+`<section class="section academic"><div class="eyebrow">John Gates / Master’s thesis project</div><h2>Research question</h2><p>${NF.question}</p><div class="status">Thesis in development. The completed document and chapters have not yet been supplied.</div>${[['Abstract','abstract'],['Literature Review Overview','literature'],['Methodology','methodology'],['Findings','findings'],['Discussion','discussion'],['Limitations','limitations'],['Future Research','future']].map(([t,k])=>`<details><summary>${t}</summary><p>${NF.thesis[k]?esc(NF.thesis[k]):`Waiting for John’s ${t.toLowerCase()}. No ${t.toLowerCase()} has been invented for this website.`}</p></details>`).join('')}<details><summary>References</summary><p>Verified academic references will be listed here and linked to their uses in the site.</p>${btn('Open sources','sources')}</details><div class="mt"><button class="btn" disabled>Download full thesis · forthcoming</button><p class="note">The download becomes available when John supplies the completed thesis.</p></div></section>`}
function sources(){return heading('Academic research library + credits','SHOW YOUR SOURCES.','Peer-reviewed research will be prioritized from approximately the last five years, with older foundational theory where needed.')+`<section class="section"><div class="controls"><div class="field"><label for="source-search">Search author, title or finding</label><input type="search" id="source-search" placeholder="Search the research library"></div>${select('source-theme','Filter by theme',['All themes',...NF.themes])}</div><p class="note">${NF.sources.length} verified academic sources currently supplied. Image credits are separate from research evidence.</p><div id="source-results" class="mt">${sourceResults()}</div><div class="mt-lg"><div class="eyebrow">Transparent by design</div><h2>WHAT EACH SOURCE WILL HOLD.</h2><div class="chips mt">${['Author','Year','Title','Journal','DOI','Theme','Finding','Where used'].map(x=>`<span class="pill">${x}</span>`).join('')}</div></div><div class="mt-lg"><div class="eyebrow">Photography, not evidence</div><h2>IMAGE CREDITS.</h2><p>Images are reused under the licenses below. Display crops may differ from the original. Share-alike image derivatives retain the original license. Team, league and athlete appearances do not imply affiliation.</p>${NF.images.map(x=>`<div class="source-card"><h4>${esc(x.alt)}</h4><p>${esc(x.caption)}</p><small><a href="${x.source}" target="_blank" rel="noopener">Source photograph</a> · ${esc(x.author)} · <a href="${x.licenseUrl}" target="_blank" rel="noopener">${x.license}</a> · display crop</small></div>`).join('')}</div></section>`}
function sourceResults(q='',theme='All themes'){const list=NF.sources.filter(s=>(theme==='All themes'||s.theme===theme)&&JSON.stringify(s).toLowerCase().includes(q.toLowerCase()));return list.length?list.map(s=>`<article class="source-card"><h3>${esc(s.title)}</h3><p>${esc(s.author)} (${esc(s.year)}) · ${esc(s.journal)}</p><p>${esc(s.finding)}</p><small>Theme: ${esc(s.theme)} · Where used: ${esc(s.whereUsed)} · DOI: ${esc(s.doi)}</small></article>`).join(''):`<div class="waiting"><h3>${q||theme!=='All themes'?'No verified sources match this filter.':'Waiting for John’s research sources.'}</h3><p>No citations have been invented. Each verified source can be added with its finding and where it is used.</p></div>`}
const views={home,journey,framework,strategy,lab,film,research,xi,about,thesis,sources};
function render(){let route=location.hash.slice(1)||'home';if(!views[route])route='home';$('#main').innerHTML=(route!=='home'?'<div class="research-banner">WORKING THESIS LAB · Conceptual framework and editorial tools. Thesis findings pending.</div>':'')+views[route]();document.title=`${routes[route]} | THE NEXT FAN`;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));$('#menu').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');window.scrollTo(0,0);wire(route)}
function modal(html){$('#detail-body').innerHTML=html;$('#detail').showModal()}
function download(name,text){const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function wire(route){document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.stage);if(route==='framework'){document.querySelectorAll('[data-stage]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});$('#stage-panel').innerHTML=stageDetail(i)}else modal(`<div class="eyebrow">The Next Fan Framework</div><h2>${NF.stages[i].name.toUpperCase()}</h2>${stageDetail(i)}${btn('Explore the whole framework','framework','blue')}`)});
if(route==='journey'){
const stories=['Eden Hazard was the starting point of my Chelsea fandom.','The player came first. The club followed.','Watching Chelsea gave that initial interest somewhere to go.','I learned more about the team beyond one player.','The culture around the club became part of the appeal.','The club began to feel like part of my identity as a fan.','Chelsea became my team. This is my personal illustration, not academic evidence.'];document.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>{$('#story-copy').textContent=stories[b.dataset.story];document.querySelectorAll('[data-story]').forEach(x=>x.classList.toggle('active',x===b))});const paths=new Set;document.querySelectorAll('[data-path]').forEach(b=>b.onclick=()=>{paths.has(b.dataset.path)?paths.delete(b.dataset.path):paths.add(b.dataset.path);b.classList.toggle('active');b.setAttribute('aria-pressed',b.classList.contains('active'));$('#path-result').textContent=paths.size?'Your routes in: '+[...paths].join(' + ')+'. Pathways can coexist. This is your reflection, not study data.':'Your pathways will appear here. This reflection is not collected as research.'});document.querySelectorAll('[data-poll]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-poll]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});$('#poll-result').textContent=`Your answer: ${b.dataset.poll}. No vote totals are being claimed. This answer stays in your current page.`});$('#quiz-form').onsubmit=e=>{e.preventDefault();const a=questions.map((_,i)=>Number($('#q'+i).value));let title,copy;if(a[0]&&a[3]&&a[9]){title='THE DIEHARD';copy='You keep showing up for the team. Even after the star leaves. That is either commitment or a very demanding hobby.'}else if(a[2]&&!a[9]){title='THE PLAYER-FIRST FAN';copy='The name on the back matters to you. Trades may require some awkward wardrobe decisions.'}else if(a[6]||a[7]){title='THE COMMUNITY FAN';copy='For you, the conversation is part of the sport. The group chat should probably have its own jersey.'}else if(a[1]&&!a[0]){title='THE HIGHLIGHT MERCHANT';copy='You prefer the condensed version. Ninety minutes? In this economy?'}else if(!a[3]&&(a[8]||a[10])){title='THE “I SWEAR I’M NOT A FAN” FAN';copy='Interesting amount of roster knowledge for someone who is just passing through.'}else if(a[2]&&!a[3]){title='THE ALGORITHM RECRUIT';copy='A player caught your attention before a team did. The nickname is playful: this quiz cannot tell how you discovered them.'}else{title='THE CASUAL';copy='You enjoy sports on your terms. There is no minimum watch-time requirement for having a good time.'}$('#quiz-result').innerHTML=`<div class="quiz-result"><div class="eyebrow">Your playful scouting report</div><h2>${title}</h2><p>${copy}</p><small>Rule-based entertainment, not scientific classification. Spending and attendance do not determine your fan worth.</small></div>`};$('#quiz-form').onreset=()=>$('#quiz-result').innerHTML='';}
if(route==='framework'){const descriptions=['Attention: a first exposure. It tells us a video was encountered, not that a fan was created.','Engagement: another view suggests continued attention in this moment. It does not show long-term attachment.','Engagement: a follow creates a possible route back. Returning is a separate behavior.','Participation: commenting contributes something, but its meaning depends on the comment and context.','Participation: joining a community creates an opportunity for belonging, not proof of identity.','Viewing behavior: watching a game is a different action from watching clips. Neither determines someone’s worth as a fan.','Commercial action: a jersey purchase may express identity or simply taste. It does not validate loyalty.','Commercial action: attendance depends on geography, cost and access as well as interest.','Commercial action: stadium food is the punchline. Concession spending is not an academic measure of loyalty.','Potential loyalty: returning over time is worth investigating alongside sustained attachment. A single repeat visit is not a validated loyalty score.'];document.querySelectorAll('[data-hotdog]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-hotdog]').forEach(x=>x.classList.toggle('active',x===b));$('#hotdog-detail').textContent=descriptions[b.dataset.hotdog]})}
if(route==='strategy'){$('#strategy-form').onsubmit=e=>{e.preventDefault();const chosen=[...document.querySelectorAll('input[name=assets]:checked')].map(x=>x.value);if(!chosen.length){$('#form-error').textContent='Choose at least one type of content to build your plan.';return}$('#form-error').textContent='';latestPlan=createPlan($('#org').value,$('#audience').value,$('#goal').value,chosen);$('#game-plan').innerHTML=planHtml(latestPlan);$('#export-plan').onclick=()=>download('The_Next_Fan_Game_Plan.txt',`THE NEXT FAN | JOHN GATES\nPROVISIONAL EDITORIAL PLAN · NOT THESIS FINDINGS\n\nOrganization: ${latestPlan.org}\nAudience: ${latestPlan.audience}\nGoal: ${latestPlan.goal}\nAvailable content: ${latestPlan.chosen.join(', ')}\n\n`+latestPlan.items.map(([k,v])=>`${k.toUpperCase()}\n${v}`).join('\n\n'))};$('#strategy-form').onreset=()=>{$('#game-plan').innerHTML='';$('#form-error').textContent='';latestPlan=null}}
if(route==='lab')document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-format]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});$('#format-panel').innerHTML=formatDetail(Number(b.dataset.format))});
if(route==='film')document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>modal(`<div class="eyebrow">Case study slot / ${b.dataset.case}</div><h2>THE STORY IS STILL TO COME.</h2>${tag('No verified case study supplied')}${['Who','What happened','Content','Audience','Fan journey stage','Why it worked / didn’t','Result','Connection to research','JG’s take'].map(t=>`<h4>${t}</h4><p class="muted">Awaiting verified material and John’s analysis.</p>`).join('')}`));
if(route==='xi')document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>modal(`<div class="eyebrow">John’s Starting XI / ${String(b.dataset.player).padStart(2,'0')}</div><h2>RESEARCH FINDING.</h2>${tag('This principle has not been written yet')}${['The principle','What the research found','Why it matters','What a sports marketer should do','Metrics','Example','JG’s take'].map(t=>`<h4>${t}</h4><p class="muted">Waiting for John’s research data.</p>`).join('')}`));
if(route==='research')document.querySelectorAll('[data-infographic]').forEach(b=>b.onclick=()=>modal(`<div class="eyebrow">Infographic brief · evidence pending</div><h2>${b.querySelector('h3').textContent}</h2><p>Purpose: make this relationship understandable without implying that a conceptual connection is a measured result.</p><h4>Evidence needed</h4><p>A verified source, the specific supported finding and any thesis data needed to visualize it.</p><h4>Current status</h4><p>Waiting for John’s research data.</p>${btn('Inspect the provisional framework','framework','blue')}`));
if(route==='sources'){const update=()=>$('#source-results').innerHTML=sourceResults($('#source-search').value,$('#source-theme').value);$('#source-search').oninput=update;$('#source-theme').onchange=update}
if(route==='about')$('#portrait-upload').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('image/'))return;const url=URL.createObjectURL(f);$('#portrait-preview').innerHTML=`<img src="${url}" alt="John’s selected professional portrait preview">`;$('#portrait-preview img').onload=()=>URL.revokeObjectURL(url)};
}
$('#menu').innerHTML=Object.entries(routes).map(([k,v])=>`<a href="#${k}">${v} ↗</a>`).join('');$('#menu-toggle').onclick=()=>{const open=$('#menu').hidden;$('#menu').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',open)};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#menu').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false')}});$('#detail .close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close()});window.addEventListener('hashchange',()=>{if($('#detail').open)$('#detail').close();render()});render();
// Licensed remote images retain a source-link fallback if a host declines hotlinking.
document.addEventListener('error',e=>{if(e.target.tagName!=='IMG')return;const image=e.target;const figure=image.closest('figure');if(figure){const link=figure.querySelector('figcaption a');const fallback=document.createElement('a');fallback.href=link?link.href:'#sources';fallback.className='image-fallback';fallback.textContent='View the licensed photograph ↗';fallback.target='_blank';fallback.rel='noopener';image.replaceWith(fallback)}else{image.style.display='none'}},true);
